function scopeDataflowReport(report, scope) {
  if (!report.checked) return report;
  if (scope.showSystem) return report;
  const mineWf = (name) => scope.hasWf(name);
  const out = {
    ...report,
    errors: report.errors.filter((e) => mineWf(e.workflow)),
    warnings: report.warnings.filter((e) => mineWf(e.workflow)),
    uncertain: report.uncertain.filter((u) => mineWf(u.workflow))
  };
  out.ok = out.errors.length === 0;
  if (report.against) {
    out.against = { ...report.against, deployed_workflows: scope.wfKeys.size, installed_apps: scope.appIds.size };
  }
  if (report.app_ids) out.app_ids = report.app_ids.filter((id) => scope.appIds.has(id));
  if (report.workflow_steps) {
    out.workflow_steps = Object.fromEntries(Object.entries(report.workflow_steps).filter(([n]) => mineWf(n)));
  }
  if (report.graph) {
    const own = /* @__PURE__ */ new Set();
    for (const n of report.graph.nodes) {
      if (n.type === "workflow" && mineWf(n.id.slice("workflow:".length))) own.add(n.id);
      else if (n.type === "app" && scope.appIds.has(n.id.slice("app:".length))) own.add(n.id);
    }
    const keepEdge = (e) => own.has(e.from) || own.has(e.to);
    const edges = report.graph.edges.filter(keepEdge).filter((e) => {
      const other = own.has(e.from) ? e.to : e.from;
      const isOwn = own.has(other);
      const t = other.split(":")[0];
      return isOwn || t === "template" || t === "missing";
    });
    const ids = new Set(own);
    for (const e of edges) {
      ids.add(e.from);
      ids.add(e.to);
    }
    out.graph = { nodes: report.graph.nodes.filter((n) => ids.has(n.id)), edges };
  }
  return out;
}

