  if (gate) return c.json({ error: gate.error, code: "engine_too_old", hint: gate.hint, needs: gate.needs, have: gate.have }, 409);
  const prev = typeof declared.id === "string" ? await getInstalledApp(c.env, apiKey, declared.id) : null;
  const warnings = [];
